import{_ as a,o as s,c as i,a2 as e}from"./chunks/framework.CqGPl1zp.js";const k=JSON.parse('{"title":"设备接入（CoAP 协议）","description":"","frontmatter":{},"headers":[],"relativePath":"iot/protocol-coap.md","filePath":"iot/protocol-coap.md","lastUpdated":null}'),o={name:"iot/protocol-coap.md"};function n(d,t,l,p,r,h){return s(),i("div",null,[...t[0]||(t[0]=[e(`<h1 id="设备接入-coap-协议" tabindex="-1">设备接入（CoAP 协议） <a class="header-anchor" href="#设备接入-coap-协议" aria-label="Permalink to &quot;设备接入（CoAP 协议）&quot;">​</a></h1><p>推荐阅读：</p><ul><li><a href="./protocol-overview">《设备接入（概述）》</a> — 建议先阅读，了解整体架构和消息格式</li><li><a href="https://help.aliyun.com/zh/iot/user-guide/coap-standard" target="_blank" rel="noreferrer">《阿里云物联网平台 —— 使用 CoAP 连接通信》</a></li></ul><p>CoAP 协议接入，由 <code>yudao-module-iot-gateway</code> 模块的 <code>protocol.coap</code> 包实现，基于 Eclipse Californium，默认端口 5683。</p><p>CoAP（Constrained Application Protocol）是专为资源受限设备设计的<strong>轻量级</strong>协议，基于 UDP 传输，采用类 REST 风格（资源路径 + POST 方法）。仅支持<strong>上行</strong>（设备 → 平台），无法下行推送。</p><h2 id="_1-整体架构" tabindex="-1">1. 整体架构 <a class="header-anchor" href="#_1-整体架构" aria-label="Permalink to &quot;1. 整体架构&quot;">​</a></h2><h3 id="_1-1-认证方式" tabindex="-1">1.1 认证方式 <a class="header-anchor" href="#_1-1-认证方式" aria-label="Permalink to &quot;1.1 认证方式&quot;">​</a></h3><p>CoAP 使用 <strong>JWT Token</strong> 进行无状态认证（与 HTTP 类似）：</p><ol><li>设备发送 <code>POST /auth</code>，携带 <code>clientId</code>、<code>username</code>、<code>password</code></li><li>网关验证成功后返回 JWT Token</li><li>后续请求通过 CoAP <strong>自定义 Option（编号 2088）</strong> 携带 Token</li></ol><blockquote><p>与 HTTP 通过 <code>Authorization</code> Header 传递 Token 不同，CoAP 使用自定义 Option 2088 传递。具体见 IotCoapAbstractHandler 的 <code>OPTION_TOKEN</code> 常量。</p></blockquote><h3 id="_1-2-资源路径" tabindex="-1">1.2 资源路径 <a class="header-anchor" href="#_1-2-资源路径" aria-label="Permalink to &quot;1.2 资源路径&quot;">​</a></h3><table tabindex="0"><thead><tr><th>资源路径</th><th>说明</th><th>Handler 类</th><th>认证</th></tr></thead><tbody><tr><td><code>POST /auth</code></td><td>设备认证，获取 Token</td><td>IotCoapAuthHandler</td><td>无</td></tr><tr><td><code>POST /auth/register/device</code></td><td><a href="./device-register">设备动态注册（一型一密）</a></td><td>IotCoapRegisterHandler</td><td>无</td></tr><tr><td><code>POST /auth/register/sub-device/:productKey/:deviceName</code></td><td><a href="./device-register">子设备动态注册</a></td><td>IotCoapRegisterSubHandler</td><td>Token</td></tr><tr><td><code>POST /topic/sys/:productKey/:deviceName/*</code></td><td>上行消息（属性 / 事件等）</td><td>IotCoapUpstreamHandler</td><td>Token</td></tr></tbody></table><p>上行消息的资源路径中，<code>*</code> 通配符部分会被转换为 IotDeviceMessageMethodEnum 消息方法（斜杠转点号），例如：</p><ul><li><code>/topic/sys/{productKey}/{deviceName}/thing/property/post</code> → method: <code>thing.property.post</code></li><li><code>/topic/sys/{productKey}/{deviceName}/thing/event/post</code> → method: <code>thing.event.post</code></li></ul><h2 id="_2-配置说明" tabindex="-1">2. 配置说明 <a class="header-anchor" href="#_2-配置说明" aria-label="Permalink to &quot;2. 配置说明&quot;">​</a></h2><p>在<strong>网关</strong>的 <code>application.yaml</code> 的 <code>yudao.iot.gateway.protocols</code> 中配置 CoAP 协议实例：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">yudao</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  iot</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    gateway</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      protocols</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">coap-json</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">          enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                    # 是否启用</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">          protocol</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">coap</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                   # 协议类型</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">          port</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5683</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                       # 监听端口（CoAP 标准端口）</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">          coap</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">            max-message-size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1024</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # 最大消息大小（字节，默认 1024）</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">            ack-timeout-ms</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2000</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # ACK 超时时间（毫秒，默认 2000）</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">            max-retransmit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # 最大重传次数（默认 4）</span></span></code></pre></div><p>对应 IotGatewayProperties.ProtocolProperties 通用配置类、和 IotCoapConfig 专属配置类。</p><blockquote><p>注意：测试前需确保 <code>enabled</code> 设置为 <code>true</code>，否则协议不会启动。</p></blockquote><h2 id="_3-快速测试【推荐】" tabindex="-1">3. 快速测试【推荐】 <a class="header-anchor" href="#_3-快速测试【推荐】" aria-label="Permalink to &quot;3. 快速测试【推荐】&quot;">​</a></h2><p>可以通过以下集成测试类快速体验，具体步骤见各类的注释：</p><table tabindex="0"><thead><tr><th>设备类型</th><th>测试类</th></tr></thead><tbody><tr><td>直连设备</td><td>IotDirectDeviceCoapProtocolIntegrationTest</td></tr><tr><td>网关设备</td><td>IotGatewayDeviceCoapProtocolIntegrationTest</td></tr><tr><td>网关子设备</td><td>IotGatewaySubDeviceCoapProtocolIntegrationTest</td></tr></tbody></table><h2 id="_4-手工测试-直连设备" tabindex="-1">4. 手工测试（直连设备） <a class="header-anchor" href="#_4-手工测试-直连设备" aria-label="Permalink to &quot;4. 手工测试（直连设备）&quot;">​</a></h2><p>CoAP 没有类似 Postman、curl 这样开箱即用的调试工具，因此暂不提供手工测试案例。<strong>请使用第 3 节的集成测试类进行测试</strong>，它已经封装好了 Option 2088 Token 传递和序列化逻辑。</p>`,24)])])}const g=a(o,[["render",n]]);export{k as __pageData,g as default};
